// Compatibility page: renders compat.json (generated by tools/support/gen_support.py from compat/matrix.json, docs/titles and compat/online.json).
// Without JavaScript, or when the fetch fails, the static tables between the compat:begin/end markers stay visible.
(function () {
  "use strict";
  var $ = function (id) { return document.getElementById(id); };
  function el(tag, cls, text) {
    var e = document.createElement(tag);
    if (cls) e.className = cls;
    if (text != null) e.textContent = text;
    return e;
  }
  var MAX_ISSUES = 4;

  function titleCard(t, stages) {
    var card = el("article", "tcard");
    card.appendChild(el("h3", null, t.name));
    card.appendChild(el("p", "meta", t.title_id + (t.version ? " · v" + t.version : "") + (t.in_matrix ? "" : " · not in the scripted matrix")));
    var chips = el("div", "chips");
    stages.forEach(function (s) {
      var st = t.stages[s.key] || "n/t", c = el("span", "chip " + st.replace("/", ""));
      c.appendChild(document.createTextNode(s.label));
      c.appendChild(el("i", null, st));
      chips.appendChild(c);
    });
    card.appendChild(chips);
    function line(label, text) {
      if (!text) return;
      var p = el("p"); p.appendChild(el("b", null, label + " ")); p.appendChild(document.createTextNode(text)); card.appendChild(p);
    }
    line("State:", t.state || "no note yet");
    line("Performance:", t.performance);
    line("iOS (deferred):", t.ios);
    if (t.known_issues && t.known_issues.length) {
      var d = el("details"), ul = el("ul");
      d.appendChild(el("summary", null, "Known issues (" + t.known_issues.length + ")"));
      t.known_issues.slice(0, MAX_ISSUES).forEach(function (i) { ul.appendChild(el("li", null, i)); });
      if (t.known_issues.length > MAX_ISSUES) ul.appendChild(el("li", null, "+" + (t.known_issues.length - MAX_ISSUES) + " more in the title note"));
      d.appendChild(ul);
      card.appendChild(d);
    }
    if (t.note) {
      var p = el("p"), a = el("a", null, "Title note");
      a.href = t.note; p.appendChild(a); card.appendChild(p);
    }
    card.dataset.search = (t.name + " " + t.title_id).toLowerCase();
    card.dataset.stages = stages.map(function (s) { return s.key + ":" + (t.stages[s.key] || "n/t"); }).join(" ");
    return card;
  }

  function renderTitles(d) {
    var grid = $("title-cards"), stages = d.stages || [];
    (d.titles || []).forEach(function (t) { grid.appendChild(titleCard(t, stages)); });
    var empty = el("p", "empty", "No title matches the filter.");
    empty.hidden = true;
    grid.appendChild(empty);
    grid.hidden = false;

    var q = $("q"), sel = $("stage");
    function apply() {
      var text = q.value.trim().toLowerCase(), want = sel.value, shown = 0;
      grid.querySelectorAll(".tcard").forEach(function (c) {
        var ok = !text || c.dataset.search.indexOf(text) >= 0;
        if (ok && want) {
          var parts = want.split(":");
          ok = parts[0] === "any" ? new RegExp(":" + parts[1] + "(\\s|$)").test(c.dataset.stages) : c.dataset.stages.split(" ").indexOf(want) >= 0;
        }
        c.hidden = !ok;
        if (ok) shown++;
      });
      empty.hidden = shown > 0;
    }
    q.addEventListener("input", apply);
    sel.addEventListener("change", apply);
    $("filters").hidden = false;

    var lg = $("stage-legend");
    Object.keys(d.stage_statuses || {}).forEach(function (k) {
      var li = el("li"); li.appendChild(el("b", null, k)); li.appendChild(document.createTextNode(" " + d.stage_statuses[k])); lg.appendChild(li);
    });
    lg.hidden = !lg.children.length;
    $("compat-meta").textContent = "Platform: " + d.platform + ". Scripted matrix last run " + (d.matrix_last_run || "never") + "; title notes are updated as work lands.";
  }

  function renderOnline(o) {
    var grid = $("online-grid"), modes = o.modes || [];
    (o.titles || []).forEach(function (t) {
      var card = el("article", "ocard"), h = el("h3", null, t.name), ul = el("ul"), none = [];
      h.appendChild(el("small", null, t.backend === "none" ? "no online" : t.backend));
      card.appendChild(h);
      modes.forEach(function (m) {
        var s = (t.modes || {})[m.key];
        if (!s) return;
        if (s.status === "unsupported") { none.push(m.label); return; }
        var li = el("li");
        li.appendChild(el("span", null, m.label));
        li.appendChild(el("em", "st " + s.status, s.status));
        li.appendChild(el("small", null, s.note + " (" + s.checked + ")"));
        ul.appendChild(li);
      });
      if (ul.children.length) card.appendChild(ul);
      if (none.length) card.appendChild(el("p", null, none.length === modes.length ? "No online or local multiplayer in this title."
        : "Not in this title: " + none.join(", ") + "."));
      grid.appendChild(card);
    });
    grid.hidden = false;
    var dl = $("online-modes");
    modes.forEach(function (m) {
      var w = el("div");
      w.appendChild(el("dt", null, m.label));
      w.appendChild(el("dd", null, m.about));
      dl.appendChild(w);
    });
    dl.hidden = !modes.length;
    $("online-meta").textContent = "Last checked " + o.last_checked + ". works · partial · broken · untested (the title has the mode, not tried on Napple yet).";
  }

  fetch("compat.json")
    .then(function (r) { if (!r.ok) throw new Error(r.status); return r.json(); })
    .then(function (d) {
      renderTitles(d);
      if (d.online) renderOnline(d.online);
      $("static").hidden = true;  // the cards replace the static tables
    })
    .catch(function () {
      $("compat-meta").textContent = "Showing the static copy of the lists below.";
    });
})();
